'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={answers:{},units:{3:'cm',4:'kg',13:'cm',14:'cm'},consent:false,avatar:'Neutral',completed:false,equipped:false,paused:false,reminders:false},history=[],current='home',flowMode=false;
const choiceMap={2:['Male','Female','Non-binary','Prefer not to say'],5:['Build Muscle','Lose Fat','Get Stronger','Improve Stamina','Build an Athletic Body','General Fitness'],6:['Beginner','Intermediate','Advanced'],7:['Home','Gym','Both'],8:['None','Basic','Full gym'],10:['10','15','20','30','45','60+'],11:['No','Yes','Unsure'],12:['Mostly seated','Light','Moderate','Very active'],15:['None','Mobility','Vision','Hearing','Other','Prefer not to say'],16:['Time','No reminders']};
const groups=['Start & onboarding','Safety & preferences','Daily quest','Player & progress','Privacy & settings','Later-phase concepts'];
const screens=[];
function add(id,title,group,ref,note,render,next){screens.push({id,title,group,ref,note,render,next});}
const btn=(text,to,cls='primary')=>`<button class="${cls}" data-go="${to}">${text}</button>`;
const action=(text,id,cls='primary')=>`<button class="${cls}" data-action="${id}">${text}</button>`;
const card=(title,body,cls='')=>`<div class="card ${cls}"><h3>${title}</h3>${body}</div>`;
const p=t=>`<p>${t}</p>`;
const avatar=()=>`<div class="avatar-wrap"><div class="avatar ${state.equipped?'accent':''}"></div></div><p class="avatar-caption">ABSTRACT AVATAR PLACEHOLDER · ORIGINAL ART TO FOLLOW</p>`;
const pct=()=>Object.keys(state.answers).length/16*100;
const safetyReady=()=>[11,15,16].every(n=>state.answers[n]);
const limited=()=>['Yes','Unsure'].includes(state.answers[11]);
const bottom=active=>`<nav class="bottom-nav" aria-label="App navigation">${[['home','⌂','Today'],['progress','↗','Progress'],['rewards','✧','Rewards'],['profile','◇','Player']].map(([id,icon,t])=>`<button data-go="${id}" class="${id===active?'active':''}"><b>${icon}</b>${t}</button>`).join('')}</nav>`;
function wrap(title,body,{back=true,eyebrow='PROJECT AWAKENING',nav=null,future=false}={}){return `<section class="screen"><div class="app-top">${back?'<button data-action="back" aria-label="Go back">←</button>':'<span class="sigil">A</span>'}<span>${eyebrow}</span><span class="tag">${nav?'E / 01':'✧'}</span></div>${future?'<div class="future-label">LATER-PHASE CONCEPT · NOT CORE MVP</div>':''}${title?`<h2 tabindex="-1">${title}</h2>`:''}${body}</section>${nav?bottom(nav):''}`;}
function qnext(n){if(n<6)return 'q'+(n+1);if(n===6)return 'avatar';if(n===11)return 'q15';if(n===15)return 'q16';if(n===16)return state.answers[16]==='Time'?'notification':'safety-ready';const seq=[7,8,9,10,12,13,14];let at=seq.indexOf(n);return at===seq.length-1?'profile':'q'+seq[at+1];}
function question(q){const n=q.id,v=state.answers[n]||'';let fields='';
 if(choiceMap[n])fields=`<div class="options">${choiceMap[n].map(o=>`<button class="option ${v===o?'selected':''}" data-option="${esc(o)}" aria-pressed="${v===o}">${esc(o)}${n===10?' minutes':''}</button>`).join('')}</div>`;
 else {let units=n===3?['cm','ft/in']:n===4?['kg','lb']:n===13||n===14?['cm','in']:[];fields=`<div class="input-row"><label class="field">${n===1?'Age in years':n===9?'Days per week':'Your measurement'}<input id="answer" type="number" inputmode="decimal" step="${n===1||n===9?'1':'any'}" min="${n===1||n===9?'1':'0.01'}" ${n===9?'max="7"':''} value="${esc(v)}" placeholder="${n===1?'18':n===9?'3':'Enter value'}"></label>${units.length?`<label class="field">Unit<select id="unit">${units.map(u=>`<option ${state.units[n]===u?'selected':''}>${u}</option>`).join('')}</select></label>`:''}</div>${n===3?'<div id="inches-wrap" '+(state.units[n]==='ft/in'?'':'hidden')+'><label class="field">Additional inches<input id="inches" type="number" min="0" max="11" value="'+(state.inches||0)+'"></label></div>':''}`;}
 if(n===16)fields+='<label class="field" id="time-wrap" '+(v==='Time'?'':'hidden')+'>Reminder time<input id="reminder-time" type="time" value="'+(state.time||'18:00')+'"></label>';
 if(n===11)fields+='<label class="field">Details (optional)<input id="injury-details" placeholder="Share only what you choose" value="'+esc(state.details||'')+'"></label>';
 if(n===8)fields+='<div id="equipment-wrap" '+(!v||v==='None'?'hidden':'')+'><label class="field">Available equipment (optional demo detail)<input id="equipment-detail" placeholder="For example, resistance bands" value="'+esc(state.equipment||'')+'"></label></div>';
 let help=n===2?'For avatar presentation only, not fitness capability.':n===3||n===4?'Required by the PRD. You can correct this later. This demo keeps answers only until reset or reload.':n===11?'This is not a diagnosis. Yes or Unsure pauses high-risk exercise assignment.':n===15?'Choose what makes the experience work for you.':n===16?'No reminders is a valid choice. Permission is only requested if you opt in.':n===13||n===14?'Optional profile completion step. Measuring-guide copy requires professional review.':n<=6?'One step closer to your player profile.':'Complete your profile at your own pace.';
 return wrap(q.question,`<div class="eyebrow">${n<=6?'ONBOARDING · '+n+' OF 6':[11,15,16].includes(n)?'BEFORE YOUR FIRST WORKOUT':'PROFILE QUESTION '+String(n).padStart(2,'0')}</div><div class="progress"><i style="width:${n<=6?n/6*100:pct()}%"></i></div>${p(help)}${fields}<p class="error" role="alert" id="error"></p><div class="actions">${action('Continue →','save-answer')}${n>6&&![11,15,16].includes(n)?btn('Finish later','profile','text-btn'):''}</div>`,{eyebrow:n<=6?'PLAYER SETUP':'YOUR PROFILE'});
}
add('welcome','Welcome',0,'§1–3, §15','Consent wording and the welcome composition are proposed. Separate marketing consent is not bundled into entry.',()=>wrap('Your next chapter<br>starts here.',`<span class="pill">THE AWAKENING BEGINS</span>${avatar()}${p('Build real-world habits. Complete quests. Watch your character evolve.')}<div class="actions">${btn('Begin awakening →','consent')}${p('<span class="small">For adults 18+. Progress reflects participation, not physical worth.</span>')}</div>`,{back:false}),'consent');
add('consent','Welcome & consent',0,'§3, §15','Prototype consent controls do not constitute final legal text. Privacy and retention terms need launch-market review.',()=>wrap('Your journey.<br>Your choice.',`${p('Training preferences and measurements help shape your quests. Review how your information is used before continuing.')}${card('You stay in control',p('Camera use and progress photos are optional. You can edit, export, or delete your information.'))}<label class="check"><input id="consent" type="checkbox" ${state.consent?'checked':''}>I agree to the proposed use of my profile and health-related answers for training personalization.</label>${btn('Review privacy controls','privacy','text-btn')}<p class="small">Draft consent wording for client review.</p><p id="error" class="error" role="alert"></p><div class="actions">${action('Continue to player setup','consent')}</div>`),'q1');
QUESTIONS.filter(q=>q.id<=6).forEach(q=>add('q'+q.id,q.question,0,'§3',q.requirement,()=>question(q),'q'+(q.id+1)));
add('age-block','Adult eligibility',0,'§2, §15','The initial beta is adults-only. No exercise entry is available from this state.',()=>wrap('This adventure<br>is for adults.',`${p('The initial beta is available to people aged 18 and over.')}<div class="actions">${btn('Correct my age','q1')}${btn('Return to welcome','welcome','secondary')}</div>`),'welcome');
add('avatar','Avatar presentation',0,'§3, §18','Proposed independent presentation picker. The PRD leaves its relationship to gender open. This selection is not an additional profile-completion field.',()=>wrap('Choose your<br>starting form.',`${avatar()}${p('A generic character, never an exact replica of your body.')}<div class="options">${['Neutral','Presentation A','Presentation B'].map(x=>`<button class="option ${state.avatar===x?'selected':''}" data-avatar="${x}" aria-pressed="${state.avatar===x}">${x}</button>`).join('')}</div><div class="actions">${btn('Meet your player →','rank')}</div>`),'rank');
add('rank','E Rank / Level 1',0,'§3, §5','All users start at E Rank / Level 1, independently of exercise ability. Completion reflects actual answers entered in this demo.',()=>wrap('Every legend<br>starts somewhere.',`<div class="hero-number">E</div><span class="pill">RANK E · LEVEL 1</span>${p('Your starting rank is the beginning of your story, not a measure of your fitness.')}${card('Player profile',`<div class="row"><span>Completion</span><strong>${pct()}%</strong></div><div class="progress"><i style="width:${pct()}%"></i></div>${p('<span class="small">'+Object.keys(state.answers).length+' of 16 valid fields · No XP for measurements</span>')}`)}<div class="actions">${btn('Prepare for my first quest','q11')}</div>`),'q11');
[11,15,16].forEach(n=>{const q=QUESTIONS.find(q=>q.id===n);add('q'+n,q.question,1,'§4, §15',q.requirement,()=>question(q),n===11?'q15':n===15?'q16':'safety-ready');});
add('notification','Notification choice',1,'§4, §15','Simulated operating-system permission sheet. Both Allow and Deny continue the app. No browser permission is requested.',()=>wrap('A nudge,<br>on your terms.',`${card('Allow reminders?',p('A reminder at '+esc(state.time||'18:00')+' can help you keep your preferred schedule.'),'purple')}${p('Declining notifications never blocks your app access.')}<div class="actions">${action('Allow reminders (demo)','allow-notifications')}${action('Don’t allow','deny-notifications','secondary')}</div>`),'safety-ready');
add('safety-ready','Safety gate result',1,'§4, §6','Only valid answers to questions 11, 15 and 16 satisfy this gate. Yes/Unsure takes a cautious branch; no high-risk assignment is shown.',()=>wrap(safetyReady()?(limited()?'A gentler<br>starting point.':'Ready for your<br>first step.'):'A few choices<br>before you begin.',`${card('Safety & preferences',[11,15,16].map(n=>`<div class="list-row"><span>${n===11?'Limitations':n===15?'Accessibility':'Reminders'}</span><strong>${esc(state.answers[n]||'Not answered')}</strong></div>`).join(''))}${p(limited()?'High-risk exercise assignment is paused. Your next step is to review limitations and seek appropriate guidance.':'Your exercise plan follows your ability and limitations, never your game rank.')}<div class="actions">${action(safetyReady()?'Continue →':'Complete required selections','safety-continue')}</div>`),'home');
add('safety-hold','Limitations & safer guidance',1,'§4, §15','No individualized safer exercise is invented. The exact professional referral and triage content remains a review item.',()=>wrap('Let’s find a<br>safer next step.',`${card('Exercise assignment paused',p('You reported an injury, pain, restriction, or uncertainty. High-risk exercise quests are paused.'),'warning')}${p('Review your limitations and seek professional assessment where appropriate. Exercise screening is not a diagnosis.')}${p('Stop exercise for pain, dizziness, or other concerning symptoms.')}<div class="actions">${btn('Review my answer','q11')}${btn('Explore my player profile','profile','secondary')}${btn('Return to Today','home','text-btn')}</div>`),'profile');
add('home','Today / Quest hub',2,'§6, §9–10','Proposed Today, Progress, Rewards and Player navigation. Quest preview uses the PRD’s beginner example, not a generated personal prescription.',()=>wrap('',`<div class="row"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>Rise, player.</h2></div><span class="pill">E RANK</span></div><div class="stat-grid"><div class="stat"><strong>01</strong><span>PLAYER LEVEL</span></div><div class="stat"><strong>${pct()}%</strong><span>PROFILE COMPLETE</span></div></div>${card('The first step',`<span class="pill">${state.completed?'SESSION RECORDED':'DAILY QUEST'}</span><h2 style="font-size:25px;margin-top:16px">Build your foundation.</h2>${p(state.completed?'Your demo session is complete. XP requires server validation.':'Supported squat. Wall push-up. A short walk.')}<div class="row small"><span>15 min · Home · Example</span><span>↗</span></div><div class="divider"></div>${action(state.completed?'View completion':'Review quest →','start-quest')}`,'purple')}${card('Build a clearer profile',p('Answer the remaining questions to support more tailored training.')+btn('Complete my profile','profile','secondary'))}<p class="small">Example content · Full exercise prescription requires the safety gate and training details.</p>`,{back:false,nav:'home'}),'quest');
add('starter-info','Training details needed',2,'§6, §18','Proposed minimum-information prompt, one of the options permitted by §6. Final starter-quest policy is an open decision in §18.',()=>wrap('A little context.<br>A better quest.',`${p('Your training time and equipment are still missing. We need this information before showing a tailored exercise plan.')}${card('Complete training details',p('Where you train, available equipment, weekly schedule, and session time.'))}${p('Client decision: confirm the minimum required starter information and the safe starter-quest policy.')}<div class="actions">${btn('Add training details','q7')}${btn('Return to Today','home','secondary')}</div>`),'q7');
add('quest','Quest details',2,'§6–7','Exact example movements and volume come from §7. Rest, intensity, demos and stop-condition details need an approved exercise catalog. No individualized prescription is generated.',()=>wrap('Build your<br>foundation.',`<span class="pill">BEGINNER · HOME · 15 MIN · EXAMPLE</span><div class="quest-list">${btn('<span>01 · LOWER BODY</span><strong>Supported squat</strong><span>2×8 · Reviewed demo required →</span>','movement','card')}${btn('<span>02 · UPPER BODY</span><strong>Wall push-up</strong><span>2×8 · Adapt to ability</span>','movement','card')}${btn('<span>03 · ENDURANCE</span><strong>Short walk</strong><span>Comfortable pace · Example only</span>','movement','card')}</div>${p('Lower volume or replace if painful. These are product examples, not individualized medical prescriptions.')}<div class="actions">${action('Choose completion mode','quest-mode')}${btn('View recovery-day example','recovery','text-btn')}</div>`),'verification');
add('movement','Movement guidance',2,'§6–7, §15','Movement-library fields are shown without inventing clinical instructions, rest intervals, intensity or demonstration media.',()=>wrap('Supported<br>squat.',`${card('Approved demo goes here','<div class="camera-frame"><div class="avatar"></div><span>PLACEHOLDER · NO EXERCISE DEMO VIDEO</span></div>','purple')}<div class="row"><span class="pill">2×8 · PRD EXAMPLE</span><span class="small">Lower body</span></div><ul><li>Instructions, intensity and rest: reviewed catalog content required.</li><li>Adaptation: lower volume or replace if painful.</li><li>Stop for pain, dizziness or other concerning symptoms.</li></ul><div class="actions">${btn('Back to quest','quest')}</div>`),'quest');
add('recovery','Recovery-day example',2,'§6–7','Recovery is included in training balance. No automatic increase in intensity with game level.',()=>wrap('Recovery is<br>part of progress.',`${card('Comfortable walk + gentle mobility',p('Recovery-day example from the PRD.'),'lime')}${p('Rest or low-impact alternatives. Weekly variety, rest and training balance take priority over dramatic daily difficulty spikes.')}<div class="actions">${btn('Back to Today','home')}</div>`),'home');
add('verification','Choose verification',2,'§8','Self-report is available. Camera is optional for supported movements only. The PRD calls pose assistance MVP in §8 but puts verification in Phase 3 in §17; launch timing needs confirmation.',()=>wrap('Your effort.<br>Your choice.',`${p('Choose how you record this quest. Camera access is never required for essential progression.')}${btn('<span class="eyebrow">SELF-REPORT</span><strong> Record it yourself</strong><p class="small">Base XP, within anti-spam caps.</p>','session','card')}${btn('<span class="eyebrow">OPTIONAL CAMERA</span><strong> Pose-assisted check</strong><p class="small">Supported exercises only. Additional badge/XP within caps.</p>','camera-consent','card')}${p('Demo values and verification are illustrative. No device camera is used.')}`),'session');
add('camera-consent','Camera consent',2,'§8, §15','Explicit consent precedes calibration. No real permission, capture, video upload or storage occurs in this prototype.',()=>wrap('See your motion.<br>Keep control.',`${p('Pose assistance can help count repetitions for supported exercises. Camera angle, lighting, occlusion and movement differences affect accuracy.')}${card('Private by design',p('Prefer on-device processing. Raw video is not uploaded or stored by default.'))}<div class="actions">${btn('Allow camera (simulation)','calibration')}${btn('Use self-report instead','session','secondary')}</div>`),'calibration');
add('calibration','Camera calibration',2,'§8','A static composition shows the intended framing step. Successful tracking and detection failures are simulated.',()=>wrap('Find your frame.',`${p('Illustrative framing preview. Final calibration instructions depend on the reviewed tracking implementation.')}<div class="camera-frame"><div class="avatar"></div><span>SIMULATED PREVIEW · CAMERA OFF</span></div><div class="actions">${btn('Simulate successful calibration','session')}${btn('Simulate tracking issue','tracking-issue','secondary')}</div>`),'session');
add('tracking-issue','Tracking fallback',2,'§8','Camera failure does not block progression. Manual correction and self-report are available.',()=>wrap('Tracking needs<br>another look.',`${card('Motion could not be confirmed',p('Angle, occlusion, lighting or movement differences may affect tracking.'),'warning')}${p('Your effort still matters. Retry, switch to self-report, or request a correction.')}<div class="actions">${btn('Continue with self-report','session')}${btn('Try calibration again','calibration','secondary')}${btn('Request correction','appeal','text-btn')}</div>`),'session');
add('session','Quest in progress',2,'§6, §15','This is an interaction demo, not a live workout. Completion is gated on profile/safety selections. Detailed exercise coaching requires the reviewed catalog.',()=>wrap('One step<br>at a time.',`<span class="pill">INTERACTION DEMO · NO LIVE TRACKING</span><div class="large-timer">${state.paused?'PAUSED':'01 / 03'}</div>${card('Supported squat',p('2×8 · Example from the PRD. Follow reviewed exercise guidance before any real training.'))}${p('Stop for pain, dizziness or other concerning symptoms.')}<div class="actions">${action('Finish example session','finish-session')}${action(state.paused?'Resume demo':'Pause demo','pause','secondary')}${btn('Stop / I feel unwell','stop','text-btn')}</div>`),'complete');
add('stop','Stop exercise',2,'§15','No diagnosis or medical treatment is provided. This is the PRD’s stop-exercise and assessment branch.',()=>wrap('Stop. Take<br>a moment.',`${card('Listen to your body',p('Stop exercise for pain, dizziness or other concerning symptoms. Seek professional assessment where needed.'),'warning')}${p('The session is not marked complete. Your game level never requires you to push through symptoms.')}<div class="actions">${btn('End session and return','home')}${btn('Update limitations','q11','secondary')}</div>`),'home');
add('complete','Quest completion',2,'§6, §8–9, §16','Completion is recorded once in memory. No real XP is granted. Values and thresholds remain open; production grants require server validation and idempotency.',()=>wrap(state.completed?'A step forward.':'Completion preview.',`<div class="hero-number">✧</div><span class="pill">${state.completed?'DEMO SESSION RECORDED':'REVIEW-ONLY STATE'}</span>${p('Consistency builds your story. Your completed effort is ready for validation.')}${card('Reward status',`<div class="list-row"><span>XP</span><strong>Pending validation</strong></div><div class="list-row"><span>Rank / level</span><strong>E / 1</strong></div>${p('<span class="small">XP caps and thresholds will be tuned in beta.</span>')}`)}<div class="actions">${btn('Complete my profile','profile')}${btn('Back to Today','home','secondary')}${btn('Correct this result','appeal','text-btn')}</div>`),'profile');
add('appeal','Correction / appeal',2,'§8','Proposed manual correction form. Submit only simulates acknowledgement; it does not send or store a real request.',()=>wrap('Make your<br>record right.',`${p('Tracking is fallible. Tell us what needs another look.')}<label class="field">Correction details<input id="appeal-text" placeholder="Describe the issue"></label><p id="error" class="error" role="alert"></p><div class="actions">${action('Submit demo correction','appeal')}${btn('Return to Today','home','secondary')}</div>`),'home');
add('profile','Player profile',3,'§3–5, §10','Completion is calculated from valid answers, not rank or fitness. The independent avatar picker does not count among the 16 fields.',()=>wrap('Your player.',`${avatar()}<div class="row"><span class="pill">E RANK · LEVEL 1</span><button data-go="avatar" class="text-btn" style="width:auto">Edit avatar</button></div>${card('Profile completion',`<div class="row"><strong>${pct()}%</strong><span class="small">${Object.keys(state.answers).length} / 16 fields</span></div><div class="progress"><i style="width:${pct()}%"></i></div>`)}<div class="options">${QUESTIONS.map(q=>`<button class="option ${state.answers[q.id]?'selected':''}" data-go="q${q.id}"><span>${esc(q.question)}<br><small>${esc(state.answers[q.id]||'Not answered')}</small></span></button>`).join('')}</div>${btn('Open settings','settings','secondary')}`,{nav:'profile'}),'q7');
[7,8,9,10,12,13,14].forEach(n=>{const q=QUESTIONS.find(q=>q.id===n);add('q'+n,q.question,3,'§4',q.requirement,()=>question(q),qnext(n));});
add('progress','Physical progress',3,'§5, §10','Illustrative measurement and performance history only. No causal or clinical claims. Photo check-ins are optional and private.',()=>wrap('Look how far<br>you’ve come.',`<span class="pill">SAMPLE HISTORY · NOT YOUR DATA</span>${card('Training consistency',`<div class="bar-chart" aria-label="Illustrative weekly activity bars, no real user data"><div style="height:30%"></div><div style="height:48%"></div><div style="height:42%"></div><div style="height:70%"></div><div style="height:62%"></div><div style="height:85%"></div></div>${p('<span class="small">W1 &nbsp; W2 &nbsp; W3 &nbsp; W4 &nbsp; W5 &nbsp; W6 · Illustrative only</span>')}`)}<div class="stat-grid"><div class="stat"><strong>Activity</strong><span>Comparable check-ins</span></div><div class="stat"><strong>Body</strong><span>Separate measurements</span></div></div>${btn('Log a check-in','checkin','secondary')}${btn('Optional private photos','photos','secondary')}${p('<br>Physical progress is separate from profile completion, level and rank.')}`,{nav:'progress'}),'checkin');
add('checkin','Measurement check-in',3,'§10','Optional recurring measurements are distinct from the initial required height/weight questions. This demo acknowledges a check-in without retaining it.',()=>wrap('A moment<br>to check in.',`${p('Optional recurring check-in. Compare measurements over time separately from strength and endurance.')}${['Weight (kg)','Waist (cm)','Chest (cm)'].map((x,i)=>`<label class="field">${x}<input id="measure-${i}" type="number" min="0.01" step="any" placeholder="Optional"></label>`).join('')}<p id="error" class="error" role="alert"></p><div class="actions">${action('Save demo check-in','checkin')}${btn('Skip for now','progress','text-btn')}</div>`),'progress');
add('photos','Optional progress photos',3,'§10, §15','Photos are never required to level up. This prototype does not request, capture or upload files.',()=>wrap('Your progress.<br>For your eyes.',`${card('Entirely optional',p('Photos are private and never required to level up. Standardized photo guidance is provided only if enabled.'))}${p('This review prototype does not capture or upload images. Photo guidance and retention rules need approval.')}<div class="actions">${action('Preview enable state','photos')}${btn('Keep photos off','progress','secondary')}</div>`),'progress');
add('rewards','Rewards collection',3,'§9–10','Cosmetic items are proposed examples. No pay-to-win stats, artificial XP threshold, or default free paid AI coaching.',()=>wrap('Wear your<br>progress.',`${p('Cosmetics celebrate participation. They never change your training ability.')}<div class="inventory">${[['✧','Aura'],['◇','Avatar skin'],['♜','Title'],['▣','Border']].map(([icon,t])=>`<button data-go="reward-detail"><b>${icon}</b>${t}<small>Concept preview</small></button>`).join('')}</div>${card('Beyond the next rank',p('Class mastery, seasons, prestige and collections are long-term concepts. Real training history is preserved.'))}`,{nav:'rewards'}),'reward-detail');
add('reward-detail','Cosmetic detail',3,'§9–10','The accent aura is an illustrative cosmetic. Preview equipping is available for review, not an earned reward claim.',()=>wrap('A new glow.',`${avatar()}<span class="pill">COSMETIC CONCEPT · PREVIEW ONLY</span>${p('An accent aura for your character. Cosmetic appearance does not affect exercise prescription, rank eligibility or ability.')}<div class="actions">${action(state.equipped?'Remove preview aura':'Preview equipped aura','equip')}${btn('Back to collection','rewards','secondary')}</div>`),'rewards');
add('settings','Settings',4,'§13, §15','Proposed grouping of required accessibility, reminders, privacy and data controls.',()=>wrap('Make it<br>your own.',`${btn('Accessibility & motion →','accessibility','card')}${btn('Reminder preference →','q16','card')}${btn('Privacy & consent →','privacy','card')}${btn('Review / edit profile →','profile','card')}<div class="actions">${btn('Return to Today','home','secondary')}</div>`),'accessibility');
add('accessibility','Accessibility settings',4,'§13, §15','Large text, reduced motion, audio-off and contrast controls demonstrate the intended experience. Final screen-reader and device testing remains necessary.',()=>wrap('Play your way.',`${p('Accessibility choices should support every part of the journey.')}<label class="check"><input type="checkbox" id="large-text" ${state.large?'checked':''}>Large text</label><label class="check"><input type="checkbox" id="reduced-motion" checked>Reduced motion</label><label class="check"><input type="checkbox" checked>Audio off</label>${p('This prototype has no sound or decorative animation. Controls include text labels and keyboard focus.')}<div class="actions">${action('Apply preferences','accessibility')}${btn('Edit accommodations answer','q15','secondary')}</div>`),'settings');
add('privacy','Privacy & consent',4,'§8, §15','Export contains only this in-memory demo profile. Delete clears it. Permission changes are simulated and are not real OS permission revocation.',()=>wrap('Your data.<br>Your control.',`${card('In this prototype',p('Answers stay in memory until reset or reload. No personal data is sent to an app backend.'))}${btn('Review / edit measurements','profile','secondary')}${action('Export demo profile','export','secondary')}${action('Revoke optional permissions','revoke','secondary')}${btn('Delete demo profile','delete','secondary')}<div class="actions">${btn('Back to settings','settings','text-btn')}</div>`),'delete');
add('delete','Delete data confirmation',4,'§15','A reversible prototype reset demonstrates a destructive action confirmation. No real account exists.',()=>wrap('Clear your<br>demo data?',`${p('This removes the profile answers and session state entered in this walkthrough. You will return to welcome.')}<div class="actions">${action('Delete demo data','delete')}${btn('Keep my data','privacy','secondary')}</div>`),'welcome');
add('coach','Paid AI coach',5,'§11, §17–18','Concept only. §11 says Phase 2+ and §17 places monetization in Phase 4. Release timing, subscription price and budgets remain unconfirmed.',()=>wrap('A coach for your<br>next chapter.',`${p('Personalized explanations, adaptation proposals, progress summaries and questions, grounded in an approved exercise catalog.')}${card('Paid subscription',p('Price and usage limits: to be defined using beta evidence.'),'purple')}${card('Your free journey continues',p('Basic quests and safe progression remain available on the free tier.'))}<div class="actions">${btn('Preview coach conversation','coach-chat')}${btn('Back to Today','home','secondary')}</div>`,{future:true}),'coach-chat');
add('coach-chat','Coach conversation concept',5,'§11','Static sample conversation. No live AI, diagnosis, diet advice or real adaptation engine.',()=>wrap('Your training<br>companion.',`${card('You',p('What can you help me with?'))}${card('Coach · sample response',p('I can explain your reviewed workout plan, summarize progress and propose adaptations within approved exercise and safety constraints.'),'purple')}${p('No medical diagnosis, crash diets or guaranteed results. Usage is metered within a paid plan.')}<div class="actions">${btn('Back to coach overview','coach')}</div>`,{future:true}),'coach');
add('social','Bosses & guilds',5,'§12, §17','Later-phase concepts only. Matching considers capability, time, goal and rank; scores follow personalized adherence, not maximum reps or weight.',()=>wrap('Stronger,<br>together.',`${card('Weekly solo boss',p('A consistency challenge against your personalized goals.'),'purple')}${card('Guild missions & seasons',p('Shared participation with moderation, anti-cheat, opt-out and accessibility parity.'))}${p('Matched PvP is a later concept. The core MVP does not include multiplayer.')}<div class="actions">${btn('Back to Today','home')}</div>`,{future:true}),'home');

function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').style.display='none',4200);}
function error(text){const el=$('#error');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}else toast(text);}
function go(id,push=true){if(!screens.some(s=>s.id===id))id='home';if(push&&current!==id)history.push(current);current=id;if(location.hash.slice(1)!==id)window.history.replaceState(null,'','#'+id);render();}
function render(){const s=screens.find(s=>s.id===current);$('#app').innerHTML=s.render();$('#app').style.fontSize=state.large?'18px':'';$('#app').scrollTop=0;document.documentElement.style.setProperty('--app-font',state.large?'16px':'13px');$('#screen-nav').innerHTML=groups.map((g,i)=>`<div class="nav-group">${String(i+1).padStart(2,'0')} / ${g.toUpperCase()}</div>${screens.filter(s=>s.group===i).map(s=>`<button class="nav-item ${current===s.id?'active':''}" data-go="${s.id}" ${current===s.id?'aria-current="page"':''}><span>${String(screens.indexOf(s)+1).padStart(2,'0')}</span><span>${esc(s.title)}</span></button>`).join('')}`).join('');$('#screen-count').textContent=screens.length+' SCREENS & STATES';$('#inspector').innerHTML=`<div class="eyebrow">SCREEN ${String(screens.indexOf(s)+1).padStart(2,'0')}</div><h2>${esc(s.title)}</h2><span class="badge">${s.group===5?'Later-phase concept':'PRD-based interaction'}</span><div class="note-title">SOURCE REQUIREMENTS</div><p>PRD V2.0 · ${s.ref}</p><div class="note-title">REVIEW NOTES</div><p>${esc(s.note)}</p><div class="note-title">WHAT IS PROPOSED</div><p>Layout, navigation, visual styling and non-PRD interface copy are design proposals. Existing requirements and exact profile questions are preserved.</p><div class="note-title">WALKTHROUGH</div><p>Use the app buttons to follow the journey. The screen index and Previous/Next controls can preview any state without changing your profile.</p><button data-action="walkthrough">Start full walkthrough →</button><div class="note-title">CLIENT DECISIONS</div><ul><li>Starter behavior with missing training details</li><li>Avatar presentation selection</li><li>Reviewed exercise guidance</li><li>XP economy and subscription price</li><li>Camera and AI-coach release timing</li></ul><p class="quote">“Profile completion is NOT a health, attractiveness or fitness score.”</p>`;}
function showFlow(){flowMode=!flowMode;$('.workspace').classList.toggle('flow-mode',flowMode);$('#flow').hidden=!flowMode;$('#view-toggle').textContent=flowMode?'View prototype':'View flow';$('#flow').innerHTML=`<div class="eyebrow">THE EXPERIENCE, END TO END</div><h2>From first step to lasting progress.</h2><p class="muted">Click a screen to open it. The primary path is shown below; the catalog includes alternate states and later-phase concepts.</p><div class="card"><strong>Welcome → Consent → 6 questions → Avatar → E Rank / Level 1 → Q11 / Q15 / Q16 → Training details → Quest → Completion → Profile</strong><div class="divider"></div><p class="muted">Under 18 → eligibility stop · Yes/Unsure limitations → safety hold · Notification denial → continue · Camera declined or tracking fails → self-report · Symptoms → stop session.</p></div>${groups.map((g,i)=>`<div class="flow-group"><h3>${String(i+1).padStart(2,'0')} / ${g}</h3><div class="flow-cards">${screens.filter(s=>s.group===i).map(s=>`<button class="flow-card" data-flow-go="${s.id}"><b>${String(screens.indexOf(s)+1).padStart(2,'0')} →</b><span>${esc(s.title)}</span><small>${s.ref}</small></button>`).join('')}</div></div>`).join('')}`;}
function gate(target){if(![1,2,3,4,5,6].every(n=>state.answers[n])){toast('Complete the six initial questions first, or use the screen index to preview states.');go('q1');return;}if(Number(state.answers[1])<18){go('age-block');return;}if(!safetyReady()){go('q11');return;}if(limited()){go('safety-hold');return;}if(![7,8,10].every(n=>state.answers[n])){go('starter-info');return;}go(target);}
function saveAnswer(){const n=Number(current.slice(1));const input=$('#answer');let value=input?input.value:state.pendingOption??state.answers[n];if(value===undefined||value==='')return error('Please enter or select an answer.');if(input){const num=Number(value);if(!Number.isFinite(num)||num<=0)return error('Please enter a positive number.');if((n===1||n===9)&&!Number.isInteger(num))return error('Please enter a whole number.');if(n===9&&num>7)return error('Choose 1–7 days.');if(n===1&&num<18){delete state.answers[1];go('age-block');return;}if(n===3&&$('#unit').value==='ft/in'){const inches=Number($('#inches').value);if(!Number.isInteger(num)||!Number.isInteger(inches)||inches<0||inches>11)return error('Use whole feet and 0–11 additional inches.');state.inches=inches;}if($('#unit'))state.units[n]=$('#unit').value;}
 if(n===16&&value==='Time'){if(!$('#reminder-time').value)return error('Choose a reminder time.');state.time=$('#reminder-time').value;}if(n===11)state.details=$('#injury-details').value;if(n===8)state.equipment=$('#equipment-detail').value;state.answers[n]=String(value);delete state.pendingOption;go(qnext(n));}
const actions={
 back(){go(history.pop()||'home',false);},
 walkthrough(){reset();},
 consent(){if(!$('#consent').checked)return error('Please review and select the consent choice to continue.');state.consent=true;go('q1');},
 'save-answer':saveAnswer,
 'allow-notifications'(){state.reminders=true;go('safety-ready');},
 'deny-notifications'(){state.reminders=false;toast('Notifications declined. You can continue.');go('safety-ready');},
 'safety-continue'(){if(!safetyReady())go('q11');else go(limited()?'safety-hold':'home');},
 'start-quest'(){if(state.completed)go('complete');else gate('quest');},
 'quest-mode'(){gate('verification');},
 'finish-session'(){if(!safetyReady()||limited()||![1,2,3,4,5,6,7,8,10].every(n=>state.answers[n])){gate('session');return;}state.completed=true;state.paused=false;go('complete');},
 pause(){state.paused=!state.paused;render();},
 appeal(){if(!$('#appeal-text').value.trim())return error('Describe the correction you want to request.');toast('Demo correction acknowledged. Nothing was sent.');go('home');},
 checkin(){const vals=[0,1,2].map(i=>$('#measure-'+i).value);if(!vals.some(Boolean))return error('Enter at least one measurement, or skip.');if(vals.some(v=>v&&(!Number.isFinite(Number(v))||Number(v)<=0)))return error('Use positive measurement values.');toast('Demo check-in acknowledged. No measurement history stored.');go('progress');},
 photos(){toast('Photo-enabled state previewed. No photos captured or uploaded.');},
 equip(){state.equipped=!state.equipped;render();toast(state.equipped?'Cosmetic preview applied.':'Cosmetic preview removed.');},
 accessibility(){state.large=$('#large-text').checked;document.body.classList.toggle('large-text',state.large);go('settings');toast('Display preferences applied.');},
 export(){const blob=new Blob([JSON.stringify({demo:true,answers:state.answers,units:state.units,notice:'Client-review prototype only'},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='awakening-demo-profile.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo profile exported.');},
 revoke(){state.reminders=false;toast('Optional permissions revoked in this demo. No real device permissions were used.');},
 delete(){reset();toast('Demo data cleared.');}
};
function reset(){state={answers:{},units:{3:'cm',4:'kg',13:'cm',14:'cm'},consent:false,avatar:'Neutral',completed:false,equipped:false,paused:false,reminders:false};history=[];document.body.classList.remove('large-text');if(flowMode)showFlow();go('welcome',false);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.flowGo){showFlow();go(b.dataset.flowGo);return;}if(b.dataset.go){delete state.pendingOption;go(b.dataset.go);return;}if(b.dataset.option!==undefined){state.pendingOption=b.dataset.option;document.querySelectorAll('.option[data-option]').forEach(el=>{const selected=el===b;el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',selected);});if($('#time-wrap'))$('#time-wrap').hidden=b.dataset.option!=='Time';if($('#equipment-wrap'))$('#equipment-wrap').hidden=b.dataset.option==='None';return;}if(b.dataset.avatar){state.avatar=b.dataset.avatar;render();return;}if(b.dataset.action)actions[b.dataset.action]?.();});
document.addEventListener('change',e=>{if(e.target.id==='unit'&&$('#inches-wrap'))$('#inches-wrap').hidden=e.target.value!=='ft/in';});
$('#view-toggle').addEventListener('click',showFlow);$('#reset').addEventListener('click',reset);$('#previous').addEventListener('click',()=>go(screens[(screens.findIndex(s=>s.id===current)-1+screens.length)%screens.length].id));$('#next').addEventListener('click',()=>go(screens[(screens.findIndex(s=>s.id===current)+1)%screens.length].id));window.addEventListener('hashchange',()=>go(location.hash.slice(1),false));
go(location.hash.slice(1)||'home',false);
